function opsStaffPage(approvals=false){return heading(approvals?'Staff activation queue':'Workers, teams & workload','Roles, approval status, assignments and shift activity in one workspace.')+stats([['Workers',state.ops.staff.length,'Sample team'],['Active',state.ops.staff.filter(w=>w.status==='Active').length,'Approved role holders'],['On shift',state.ops.staff.filter(w=>w.shift).length,'Consent-based activity'],['Open tasks',state.ops.tasks.filter(t=>t.status!=='Completed').length,'Assigned work']])+card('Staff directory',table(['Worker / team','Role','Base state / town','Status','Workload','Actions'],state.ops.staff.map(w=>[esc(w.name)+'<small>'+esc(w.team)+'</small>',esc(w.role),esc(w.town+', '+w.region),badge(w.status,w.status==='Active'?'':'warn'),state.ops.tasks.filter(t=>t.staffId===w.id&&t.status!=='Completed').length,button(w.status==='Active'?'Suspend':'Approve',`opsStaffStatus('${w.id}','${w.status==='Active'?'Suspended':'Active'}')`,w.status==='Active'?'danger':'secondary')]))+note('Manager authorization is required. Suspension ends shift sharing and blocks worker mutations. No supplier accounts are created.'))+(!approvals?primaryForm('Add sample worker',`<div class="form-grid">${field('ops-staff-name','Staff display name','','text','required')}${select('ops-staff-role','Role',['Catalog','Procurement','Delivery','Fieldworker'],'Catalog')}${field('ops-staff-team','Team','Catalog','text','required')}${select('ops-staff-state','Base state',Object.keys(NG_TOWNS).sort(),'Lagos')}</div>`+note('A new worker starts Pending approval and receives no active access.'),"opsAddStaff()",'Create pending staff profile'):'')+card('Team tools',links([['A06','Assign visits, pickups and deliveries'],['A34','Review worker check-ins'],['A03','Role and assignment scope'],['A27','Team performance and operational reporting']]));}
function opsStaffStatus(id,status){if(state.staffActor!=='Manager'){toast('Switch the sample admin reviewer to Manager to activate or suspend staff.');return;}const w=state.ops.staff.find(w=>w.id===id);w.status=status;if(id==='ST-01')state.staffStatus=status;if(status!=='Active'){w.shift=false;opsDevicePositions.delete(id);}opsLog('Staff '+w.name+' '+status,'Manager');render();}
function opsAddStaff(){const name=$('ops-staff-name').value.trim();if(!name)return;const region=$('ops-staff-state').value;state.ops.staff.push({id:'ST-'+Date.now(),name,role:$('ops-staff-role').value,team:$('ops-staff-team').value,status:'Pending approval',region,town:NG_TOWNS[region][0],shift:false,lastSeen:null});opsLog('Pending staff profile created: '+name,'Manager');render();}
