function opsAssignTask(){const w=state.ops.staff.find(w=>w.name===$('ops-task-worker').value&&w.status==='Active');if(!w){toast('Approve a worker before assigning work.');return;}const type=$('ops-task-type').value;const allowed={Catalog:['Supplier visit'],Procurement:['Supplier pickup'],Delivery:['Delivery','Return collection'],Fieldworker:['Supplier visit','Supplier pickup','Delivery','Return collection']};if(!(allowed[w.role]||[]).includes(type)){toast('This task type is outside the worker’s role.');return;}state.ops.tasks.push({id:'TASK-'+Date.now(),type,staffId:w.id,reference:$('ops-task-ref').value,sku:$('ops-task-sku').value,qty:Number($('ops-task-qty').value),region:$('ops-task-region').value,town:$('ops-task-town').value,status:'Assigned',due:Date.now()+Number($('ops-task-hours').value)*3600000});opsLog('Assigned '+type+' to '+w.name,'Manager');render();}
