function opsReceive(id){if(!opsRequire('procurement'))return;const task=state.ops.tasks.find(t=>t.id===id);if(!task||task.staffId!==opsWorker().id){toast('This pickup is not assigned to you.');return;}if(state.ops.receipts.some(r=>r.taskId===id)){toast('Receipt already recorded. Assign a follow-up task for further goods.');return;}const accepted=Number($('ops-accepted').value),rejected=Number($('ops-rejected').value);if(!Number.isInteger(accepted)||!Number.isInteger(rejected)||accepted<0||rejected<0||accepted+rejected!==task.qty){toast('Accepted plus rejected must equal the assigned quantity.');return;}state.ops.receipts.push({taskId:id,sku:task.sku,expected:task.qty,accepted,rejected,note:$('ops-inspect-note').value,actor:opsWorker().name,at:Date.now()});task.status=rejected?'Blocked':'Completed';state.inspection=accepted>0;state.pickup=accepted>0;opsLog('Inspected pickup '+id+': '+accepted+' accepted; '+rejected+' rejected');render();}
