function opsConfirmDelivery(){if(!opsRequire('delivery'))return;const t=opsCurrentTask('Delivery');if(!t||t.staffId!==opsWorker().id||!state.dispatch){toast('An assigned delivery and dispatched shipment are required.');return;}if($('ops-delivery-otp').value!=='123456'){toast('The sample verification code is incorrect.');return;}t.status='Completed';t.completedAt=Date.now();state.delivery=true;opsLog('Confirmed delivery '+t.id+' with customer code');render();}
