function opsSaveVisitConsent(){if(!opsRequire('visit'))return;const d=opsEnsureDraft();d.rights=$('ops-visit-consent').checked;d.rightsRef=$('ops-visit-rights').value;state.consent=d.rights;opsLog('Supplier capture consent recorded: '+d.rightsRef);go('W04');}
function opsRecordAvailability(){if(!opsRequire('procurement'))return;const task=opsCurrentTask('Supplier pickup');if(!task)return;state.ops.availability=state.ops.availability||[];const quantity=Number($('ops-available').value);if(!Number.isInteger(quantity)||quantity<0){toast('Enter a valid whole unit quantity.');return;}state.ops.availability.unshift({sku:task.sku,quantity,source:$('ops-stock-source').value,note:$('ops-stock-note').value,actor:opsWorker().name,at:Date.now()});if(quantity<task.qty){task.status='Blocked';task.issue='Supplier stock below assigned quantity';}opsLog('Confirmed supplier availability: '+task.sku+' / '+quantity+' units');render();}
