function opsRecordCash(){if(!opsRequire('cash'))return;const amount=Number($('ops-cash-amount').value),reference=$('ops-cash-note').value.trim();if(!Number.isInteger(amount)||amount<=0||!reference){toast('Enter a valid whole-naira amount and unique evidence reference.');return;}state.ops.cashRecords=state.ops.cashRecords||[];const old=state.ops.cashRecords.find(c=>c.reference===reference);if(old){toast(old.amount===amount?'This collection was already recorded.':'Reference conflict: use the original amount or a new collection reference.');return;}if(state.cashReconciled){toast('The historical sample has already been reconciled.');return;}state.ops.cashRecords.push({amount,reference,actor:opsWorker().name,at:Date.now()});state.cashCollected=true;opsLog('Recorded unreconciled cash '+amount+' / '+reference);render();}
const opsCashAdmin=adminPage;
adminPage=id=>{if(id!=='A18')return opsCashAdmin(id);const collections=state.ops.cashRecords||[],received=collections.reduce((n,c)=>n+c.amount,0);return heading('COD cash handover & reconciliation','Worker collection and finance verification remain separate.')+card('Historical COD sample',row('Expected cash',money(53000))+row('Worker-recorded cash',money(received))+row('Variance',money(received-53000))+row('Finance state',badge(state.cashReconciled?'Reconciled':'Unreconciled','warn'))+table(['Reference','Amount','Collected by','Time'],collections.map(c=>[esc(c.reference),money(c.amount),esc(c.actor),opsTime(c.at)]))+button('Verify sample handover','opsReconcileCash()','',state.cashReconciled)+note('A variance blocks reconciliation and needs investigation. This is the separate historical COD sample, not the current online-paid order.'))+links([['W13','Worker cash collection'],['A29','Audit trail']]);};
function opsReconcileCash(){if(state.staffActor!=='Manager'){toast('An authorized finance approver is required in this sample.');return;}const received=(state.ops.cashRecords||[]).reduce((n,c)=>n+c.amount,0);if(received!==53000){toast('Cash variance: investigate before confirming reconciliation.');return;}state.cashReconciled=true;opsLog('Finance verified exact historical COD handover','Manager');render();}

