workerPage=id=>{if(id==='W07'){const t=opsCurrentTask('Supplier pickup');return heading('Supplier availability confirmation','Assigned SKU, confirmed quantity, source and freshness.')+opsTaskCard(t)+(t?primaryForm('Supplier confirmation',row('SKU',esc(t.sku))+field('ops-available','Available selling units',t.qty,'number','required min="0" max="100000"')+select('ops-stock-source','Source',['Phone','WhatsApp','In-person visit'],'In-person visit')+field('ops-stock-note','Evidence note','Sample supplier confirmation','text','required'),"opsRecordAvailability()",'Record availability'):'');}if(id==='W13')return heading('Assigned-role cash collection','A worker record never marks bank settlement or finance reconciliation complete.')+primaryForm('Historical sample COD collection',row('Reference','CLC-COD-DEMO · separate from current online order')+field('ops-cash-amount','Cash received NGN',53000,'number','required min="1" max="1000000"')+field('ops-cash-note','Collection evidence','CASH-DEMO-001','text','required')+note('Requires an active cash-handling role. Finance verifies the actual handover.'),"opsRecordCash()",'Record unreconciled collection')+card('Status',row('Collection',state.cashCollected?'Recorded':'Expected')+row('Finance reconciliation',state.cashReconciled?'Reconciled':'Outstanding')+link('A18','Finance handover →'));if(id==='W14')return heading('Assigned return collection','Record returned units and condition; refund approval remains separate.')+opsTaskCard(opsCurrentTask('Return collection'))+primaryForm('Returned goods',field('ops-return-qty','Units collected',1,'number','required min="1" max="100000"')+field('ops-return-note','Condition / evidence','Sample return package','text','required'),"if(!opsRequire('delivery'))return;if(!opsCurrentTask('Return collection')){toast('A return task must be assigned first.');return;}opsCurrentTask('Return collection').status='Completed';opsLog('Collected assigned return units '+$('ops-return-qty').value);render();",'Record return collection');return opsWorkerGuarded(id);};
